// Builds the Gift Registry icon comps from gen/icons.json (generated by gen/motion.py). ASCII only.
// Creates/replaces only comps carrying TAG inside the folder "05 Icon lotties (18 Nov asset pack)"; touches nothing else.
// $.global.ICON_ONLY = "<comp name>" builds just that comp.
var DATA = /*DATA*/null;
var TAG = "gr-icons-builder";
var FOLDER = "05 Icon lotties (18 Nov asset pack)";
var ART_FOLDER = "_icon art (asset pack parts)";

function findFolder(name, parent) {
  for (var i = 1; i <= app.project.numItems; i++) {
    var it = app.project.item(i);
    if (it instanceof FolderItem && it.name === name && it.parentFolder === parent) return it;
  }
  var f = app.project.items.addFolder(name); f.parentFolder = parent; return f;
}
function easeDims(prop) {
  var t = prop.propertyValueType;
  if (t === PropertyValueType.TwoD) return prop.isSpatial ? 1 : 2;
  if (t === PropertyValueType.ThreeD) return prop.isSpatial ? 1 : 3;
  return 1;
}
function sameVal(a, b) {
  if (typeof a === "number") return Math.abs(a - b) < 1e-6;
  for (var q = 0; q < a.length; q++) if (Math.abs(a[q] - b[q]) > 1e-6) return false;
  return true;
}
function setKeys(prop, keys) {
  var i, d;
  for (i = 0; i < keys.length; i++) prop.setValueAtTime(keys[i][0], keys[i][1]);
  for (i = 0; i < keys.length; i++) {
    var idx = prop.nearestKeyIndex(keys[i][0]);
    prop.setInterpolationTypeAtKey(idx, KeyframeInterpolationType.BEZIER, KeyframeInterpolationType.BEZIER);
    var n = easeDims(prop), ei = [], eo = [];
    for (d = 0; d < n; d++) { ei.push(new KeyframeEase(0, Math.max(0.1, keys[i][2]))); eo.push(new KeyframeEase(0, Math.max(0.1, keys[i][3]))); }
    prop.setTemporalEaseAtKey(idx, ei, eo);
    // a rest between two equal keys becomes a HOLD: exporters turn equal-value bezier segments into bad handles (a jump)
    if (i + 1 < keys.length && sameVal(keys[i][1], keys[i + 1][1]))
      prop.setInterpolationTypeAtKey(idx, KeyframeInterpolationType.BEZIER, KeyframeInterpolationType.HOLD);
  }
}
function mapKeys(keys, fn) {
  var out = [];
  for (var i = 0; i < keys.length; i++) out.push([keys[i][0], fn(keys[i][1]), keys[i][2], keys[i][3]]);
  return out;
}
function tr(layer, mn) { return layer.property("ADBE Transform Group").property(mn); }

var root = app.project.rootFolder;
var F = findFolder(FOLDER, root);
var AF = findFolder(ART_FOLDER, F);
var footage = {};
for (var i = 1; i <= AF.numItems; i++) { var it = AF.item(i); if (it instanceof FootageItem && it.file) footage[it.file.fsName] = it; }
function getFootage(rel) {
  var path = DATA.root + "/" + (rel.indexOf("art/") === 0 ? rel : "assets/" + rel);
  var f = new File(path);
  if (footage[f.fsName]) return footage[f.fsName];
  var io = new ImportOptions(f);
  var it = app.project.importFile(io); it.parentFolder = AF;
  it.mainSource.alphaMode = AlphaMode.STRAIGHT;
  footage[f.fsName] = it; return it;
}

var built = [];
for (var c = 0; c < DATA.icons.length; c++) {
  var I = DATA.icons[c];
  if ($.global.ICON_ONLY && $.global.ICON_ONLY !== I.comp) continue;
  // replace an earlier build of this comp (only ones this builder made)
  for (var k = F.numItems; k >= 1; k--) { var old = F.item(k); if (old instanceof CompItem && old.name === I.comp && old.comment === TAG) old.remove(); }
  var C = app.project.items.addComp(I.comp, 600, 600, 1, DATA.dur, DATA.fps);
  C.parentFolder = F; C.comment = TAG; C.bgColor = [1, 1, 1];
  for (var j = I.layers.length - 1; j >= 0; j--) {
    var S = I.layers[j];
    var L = C.layers.add(getFootage(S.file));
    L.name = S.name; L.comment = TAG;
    var s = S.s, px = S.pivot[0], py = S.pivot[1];
    tr(L, "ADBE Anchor Point").setValue([(px - S.x) / s, (py - S.y) / s]);
    var P = tr(L, "ADBE Position"); P.dimensionsSeparated = true;
    var PX = tr(L, "ADBE Position_0"), PY = tr(L, "ADBE Position_1");
    if (S.dx) setKeys(PX, mapKeys(S.dx, function (v) { return px + v; })); else PX.setValue(px);
    if (S.dy) setKeys(PY, mapKeys(S.dy, function (v) { return py + v; })); else PY.setValue(py);
    var SC = tr(L, "ADBE Scale");
    if (S.sc) setKeys(SC, mapKeys(S.sc, function (v) { return [v[0] * s, v[1] * s]; })); else SC.setValue([s * 100, s * 100]);
    var R = tr(L, "ADBE Rotate Z");
    if (S.rot) setKeys(R, mapKeys(S.rot, function (v) { return v + DATA.rot0; })); else R.setValue(DATA.rot0);
    if (S.op) setKeys(tr(L, "ADBE Opacity"), S.op);
  }
  built.push(I.comp + " (" + C.numLayers + ")");
}
$.global.RESULT = "built: " + built.join(" | ");
